18	package org.apache.flink.runtime.checkpoint.filemerging;
19	
20	import org.apache.flink.core.fs.FSDataInputStream;
21	import org.apache.flink.core.fs.FileSystem;
22	import org.apache.flink.core.fs.Path;
23	import org.apache.flink.runtime.state.CheckpointedStateScope;
24	import org.apache.flink.runtime.state.PhysicalStateHandleID;
25	import org.apache.flink.runtime.state.StreamStateHandle;
26	import org.apache.flink.runtime.state.filesystem.FileStateHandle;
27	import org.apache.flink.runtime.state.filesystem.FsSegmentDataInputStream;
28	
29	import java.io.IOException;
30	import java.util.Objects;
31	import java.util.Optional;
32	
33	/**
34	 * {@link FileStateHandle} for state that was written to a file segment. A {@link
35	 * SegmentFileStateHandle} represents a {@link LogicalFile}, which has already been written to a
36	 * segment in a physical file.
37	 *
38	 * <p>TODO (FLINK-32079): serialization and deserialization of {@link SegmentFileStateHandle}.
39	 */
40	public class SegmentFileStateHandle implements StreamStateHandle {
41	
42	    private static final long serialVersionUID = 1L;
43	
44	    /** The path to the file in the filesystem, fully describing the file system. */
45	    private final Path filePath;
46	
47	    /** The size of the state in the file. */
48	    protected final long stateSize;
49	
50	    /** The starting position of the segment in the file. */
51	    private final long startPos;
52	
53	    /** The scope of the state. */
54	    private final CheckpointedStateScope scope;
55	
56	    /**
57	     * Creates a new segment file state for the given file path.
58	     *
59	     * @param filePath The path to the file that stores the state.
60	     * @param startPos Start position of the segment in the physical file.
61	     * @param stateSize Size of the segment.
62	     * @param scope The state's scope, whether it is exclusive or shared.
63	     */
64	    public SegmentFileStateHandle(
65	            Path filePath, long startPos, long stateSize, CheckpointedStateScope scope) {
66	        this.filePath = filePath;
67	        this.stateSize = stateSize;
68	        this.startPos = startPos;
69	        this.scope = scope;
70	    }
71	
72	    /**
73	     * This method should be empty, so that JM is not in charge of the lifecycle of files in a
74	     * file-merging checkpoint.
75	     */
76	    @Override
77	    public void discardState() {}
78	
79	    /**
80	     * Gets the path where this handle's state is stored.
81	     *
82	     * @return The path where this handle's state is stored.
83	     */
84	    public Path getFilePath() {
85	        return filePath;
86	    }
87	
88	    @Override
89	    public FSDataInputStream openInputStream() throws IOException {
90	        FSDataInputStream inputStream = getFileSystem().open(filePath);
91	        return new FsSegmentDataInputStream(inputStream, startPos, stateSize);
92	    }
93	
94	    @Override
95	    public Optional<byte[]> asBytesIfInMemory() {
96	        return Optional.empty();
97	    }
98	
99	    @Override
100	    public PhysicalStateHandleID getStreamStateHandleID() {
101	        return new PhysicalStateHandleID(filePath.toUri().toString());
102	    }
103	
104	    public long getStartPos() {
105	        return startPos;
106	    }
107	
108	    @Override
109	    public long getStateSize() {
110	        return stateSize;
111	    }
112	
113	    public CheckpointedStateScope getScope() {
114	        return scope;
115	    }
116	
117	    /**
118	     * Gets the file system that stores the file state.
119	     *
120	     * @return The file system that stores the file state.
121	     * @throws IOException Thrown if the file system cannot be accessed.
122	     */
123	    private FileSystem getFileSystem() throws IOException {
124	        return FileSystem.get(filePath.toUri());
125	    }
126	
127	    // ------------------------------------------------------------------------
128	
129	    @Override
130	    public boolean equals(Object o) {
131	        if (this == o) {
132	            return true;
133	        }
134	
135	        if (o == null || getClass() != o.getClass()) {
136	            return false;
137	        }
138	
139	        SegmentFileStateHandle that = (SegmentFileStateHandle) o;
140	
141	        return super.equals(that)
142	                && startPos == that.startPos
143	                && stateSize == that.stateSize
144	                && scope.equals(that.scope);
145	    }
146	
147	    @Override
148	    public int hashCode() {
149	        int result = getFilePath().hashCode();
150	        result = 31 * result + Objects.hashCode(startPos);
151	        result = 31 * result + Objects.hashCode(stateSize);
152	        result = 31 * result + Objects.hashCode(scope);
153	        return result;
154	    }
155	
156	    @Override
157	    public String toString() {
158	        return String.format(
159	                "Segment File State: %s [Starting Position: %d, %d bytes]",
160	                getFilePath(), startPos, stateSize);
161	    }
162	}
