/**
 * A {@link OperatorStreamStateHandle} that works for file-merging checkpoints. Besides the operator
 * state, it also tracks the managed directories of the file-merging checkpoint (the shared subtask
 * directory and the {@code taskowned/} directory), so that these directories are registered to the
 * {@link SharedStateRegistry} and will not be deleted until they are no longer referenced by any
 * active checkpoint. This is necessary even for operators without any state, so that the managed
 * directories are still maintained correctly across the checkpoint lifecycle.
 */
public class FileMergingOperatorStreamStateHandle extends OperatorStreamStateHandle
        implements CompositeStateHandle {

    private static final Logger LOG =
            LoggerFactory.getLogger(FileMergingOperatorStreamStateHandle.class);

    private static final long serialVersionUID = 1L;

    /** The handle of the {@code taskowned/} directory, holding the exclusive/private state. */
    private final DirectoryStreamStateHandle taskOwnedDirHandle;

    /** The handle of the shared subtask directory, holding the shared state. */
    private final DirectoryStreamStateHandle sharedDirHandle;

    /**
     * The registry to which this handle registers its shared states. This is used to make sure that
     * this handle does not register twice with the same registry.
     */
    private transient SharedStateRegistry sharedStateRegistry;

    public FileMergingOperatorStreamStateHandle(
            DirectoryStreamStateHandle taskOwnedDirHandle,
            DirectoryStreamStateHandle sharedDirHandle,
            Map<String, StateMetaInfo> stateNameToPartitionOffsets,
            StreamStateHandle delegateStateHandle) {
        super(stateNameToPartitionOffsets, delegateStateHandle);
        this.taskOwnedDirHandle = Preconditions.checkNotNull(taskOwnedDirHandle);
        this.sharedDirHandle = Preconditions.checkNotNull(sharedDirHandle);
    }

    @Override
    public void registerSharedStates(SharedStateRegistry stateRegistry, long checkpointID) {
        // This is a quick check to avoid that we register twice with the same registry. The
        // ownership of the managed directories is transferred to the registry after registration,
        // so that they will not be discarded until no longer referenced by any active checkpoint.
        Preconditions.checkState(
                sharedStateRegistry != stateRegistry,
                "The state handle has already registered its shared states to the given registry.");

        sharedStateRegistry = Preconditions.checkNotNull(stateRegistry);

        stateRegistry.registerReference(
                taskOwnedDirHandle.createStateRegistryKey(), taskOwnedDirHandle, checkpointID);
        stateRegistry.registerReference(
                sharedDirHandle.createStateRegistryKey(), sharedDirHandle, checkpointID);
        stateRegistry.registerReference(
                SharedStateRegistryKeyForDelegate(), getDelegateStateHandle(), checkpointID);
    }

    private org.apache.flink.runtime.state.SharedStateRegistryKey SharedStateRegistryKeyForDelegate() {
        return org.apache.flink.runtime.state.SharedStateRegistryKey.forStreamStateHandle(
                getDelegateStateHandle());
    }

    @Override
    public void discardState() throws Exception {
        try {
            super.discardState();
        } catch (Exception e) {
            LOG.warn("Failed to discard the delegate state handle of {}.", this, e);
        }
    }

    @Override
    public long getCheckpointedSize() {
        return getStateSize();
    }

    public DirectoryStreamStateHandle getTaskOwnedDirHandle() {
        return taskOwnedDirHandle;
    }

    public DirectoryStreamStateHandle getSharedDirHandle() {
        return sharedDirHandle;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        if (!super.equals(o)) {
            return false;
        }
        FileMergingOperatorStreamStateHandle that = (FileMergingOperatorStreamStateHandle) o;
        return Objects.equals(taskOwnedDirHandle, that.taskOwnedDirHandle)
                && Objects.equals(sharedDirHandle, that.sharedDirHandle);
    }

    @Override
    public int hashCode() {
        int result = super.hashCode();
        result = 31 * result + Objects.hashCode(taskOwnedDirHandle);
        result = 31 * result + Objects.hashCode(sharedDirHandle);
        return result;
    }

    @Override
    public String toString() {
        return "FileMergingOperatorStreamStateHandle{"
                + "taskOwnedDirHandle="
                + taskOwnedDirHandle
                + ", sharedDirHandle="
                + sharedDirHandle
                + ", operatorStreamStateHandle="
                + super.toString()
                + '}';
    }
