public class EmptySegmentFileStateHandle extends SegmentFileStateHandle {

    private static final long serialVersionUID = 1L;

    /** A singleton instance of the empty segment file state handle. */
    public static final EmptySegmentFileStateHandle INSTANCE = new EmptySegmentFileStateHandle();

