        super(new Path("empty"), 0, 0, CheckpointedStateScope.SHARED);
    }

    @Override
    public FSDataInputStream openInputStream() throws IOException {
        throw new UnsupportedOperationException(
                "Cannot open an input stream for an empty segment file state handle.");
    }
}
