        super(taskOwnedDirHandle, sharedDirHandle, stateNameToPartitionOffsets, delegateStateHandle);
    }

    /**
     * Create an {@link EmptyFileMergingOperatorStreamStateHandle} that carries no operator state but
     * still tracks the managed directories.
     *
     * @param taskownedDirHandle the handle of the {@code taskowned/} directory.
     * @param sharedDirHandle the handle of the shared subtask directory.
     * @return the created handle.
     */
    public static EmptyFileMergingOperatorStreamStateHandle create(
            DirectoryStreamStateHandle taskownedDirHandle,
            DirectoryStreamStateHandle sharedDirHandle) {
        return new EmptyFileMergingOperatorStreamStateHandle(
                taskownedDirHandle,
                sharedDirHandle,
                Collections.emptyMap(),
                EmptySegmentFileStateHandle.INSTANCE);
    }
}
